// Post-processor ground truth: RoboDK's own posts (tests/fixtures/posts_gt/cases/<case>/<RoboDK post>/, generated by
// gen_gt.py from the same job.json) vs the studio's built-in posts. Files must match token by token: text tokens
// exactly, numbers within 1e-3; blank lines, date/time lines and "generated by" comment lines are ignored.
import { describe, it, expect } from 'vitest';
import { readFileSync } from 'node:fs';
import path from 'node:path';
import { cases, diffArchives, diffPrograms, generateForCase, STRICT } from './posts_gt_util';

const ALL = cases();
describe('posts GT (RoboDK original posts vs studio posts)', () => {
  it('fixtures are present (feature program for every P0 post + >= 20 Library programs)', () => {
    expect(ALL.filter((c) => c.name.startsWith('feature_')).length).toBeGreaterThanOrEqual(20);
    expect(new Set(ALL.filter((c) => c.name.startsWith('lib_')).map((c) => c.name)).size).toBeGreaterThanOrEqual(20);
  });
  for (const c of ALL.filter((x) => STRICT.includes(x.post))) {
    it(`${c.name} / ${c.post}`, () => {
      const files = generateForCase(c);
      const got = new Map(files.map((f) => [f.name.toLowerCase(), f]));
      for (const name of c.files) {
        const f = got.get(name.toLowerCase());
        expect(f, `missing file ${name} (studio wrote ${files.map((x) => x.name).join(', ')})`).toBeTruthy();
        const raw = readFileSync(path.join(c.dir, name));
        if (f!.encoding === 'base64') {
          const d = diffArchives(raw, Buffer.from(f!.content, 'base64'));
          expect(d, `${name}: ${d}`).toBeNull();
          continue;
        }
        const exp = raw.toString('utf8');
        const d = diffPrograms(exp, f!.content);
        expect(d, `${name}: ${d}`).toBeNull();
      }
      expect(files.length, `extra files: ${files.map((x) => x.name).join(', ')} vs ${c.files.join(', ')}`).toBe(c.files.length);
    });
  }
});
